// 지난 7일 장애 + 최신 요금 → 주간 리포트 (HTML)
const now = $now.setZone('Asia/Seoul');
const end = now.toMillis();
const start = end - 7 * 864e5;
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const num = v => (v === '' || v == null) ? null : Number(v);
const isTrue = v => v === true || String(v).toUpperCase() === 'TRUE';
const fmtMin = m => m >= 60 ? `${Math.floor(m / 60)}시간 ${Math.round(m % 60)}분` : `${Math.round(m)}분`;
const kst = iso => iso ? $now.constructor.fromISO(iso).setZone('Asia/Seoul').toFormat('MM/dd HH:mm') : '';

// ---------- 장애 ----------
const incidents = $('장애 기록 읽기').all().map(i => i.json).filter(r => r.incident_key);
const PROVIDERS = ['GCP', 'AWS', 'Azure'];
const SEOUL = /seoul|korea|asia-northeast3|ap-northeast-2|koreacentral/i;
const inWin = [];
for (const r of incidents) {
  const s = Date.parse(r.started_at);
  if (isNaN(s)) continue;
  const e = r.ended_at ? Date.parse(r.ended_at) : end;
  if (s >= end || e <= start) continue;
  const mins = (Math.min(e, end) - Math.max(s, start)) / 60000;
  inWin.push({ ...r, mins, ongoing: !r.ended_at || r.status === 'ongoing' });
}
const byProv = PROVIDERS.map(p => {
  const rows = inWin.filter(r => r.provider === p);
  return { p, count: rows.length, mins: rows.reduce((a, r) => a + r.mins, 0),
           ongoing: rows.filter(r => r.ongoing).length, seoul: rows.filter(r => SEOUL.test(`${r.regions} ${r.title}`)).length };
});
const top = [...inWin].sort((a, b) => b.mins - a.mins).slice(0, 5);
const seoulRows = inWin.filter(r => SEOUL.test(`${r.regions} ${r.title}`));

// ---------- 요금 ----------
const prices = $input.all().map(i => i.json).filter(r => r.price_key);
// 제공사별로 각자 가장 최근 날짜를 사용 (한 제공사 수집이 실패한 날에도 표가 비지 않도록)
const latestBy = {};
for (const r of prices) {
  const d = String(r.date);
  if (!latestBy[r.provider] || d > latestBy[r.provider]) latestBy[r.provider] = d;
}
const latestDate = Object.values(latestBy).sort().pop() || '';
const latest = prices.filter(r => String(r.date) === latestBy[r.provider])
  .map(r => ({ ...r, hourly: num(r.hourly_usd), monthly: num(r.monthly_usd) }))
  .sort((a, b) => a.pricing.localeCompare(b.pricing) || a.hourly - b.hourly);
const startDate = $now.constructor.fromMillis(start).setZone('Asia/Seoul').toFormat('yyyy-MM-dd');
const changes = prices.filter(r => String(r.date) >= startDate && isTrue(r.changed));
const od = latest.filter(r => r.pricing === 'OnDemand');
const sp = latest.filter(r => r.pricing === 'Spot');
const cheapOD = od[0], dearOD = od[od.length - 1], cheapSpot = sp[0];

// ---------- 핵심 인사이트 ----------
const insights = [];
const worst = [...byProv].sort((a, b) => b.mins - a.mins)[0];
if (worst && worst.mins > 0) insights.push(`지난 7일 장애 지속시간이 가장 긴 곳은 <b>${worst.p}</b>(${worst.count}건, 누적 ${fmtMin(worst.mins)})입니다.`);
else insights.push('지난 7일 동안 수집된 장애가 없습니다.');
insights.push(seoulRows.length ? `서울 리전 관련 장애가 <b>${seoulRows.length}건</b> 있었습니다.` : '서울 리전 관련 장애는 없었습니다.');
if (cheapOD && dearOD && cheapOD !== dearOD) {
  const gap = ((dearOD.hourly - cheapOD.hourly) / dearOD.hourly * 100).toFixed(1);
  insights.push(`온디맨드 최저가는 <b>${esc(cheapOD.provider)} ${esc(cheapOD.instance)}</b>($${cheapOD.hourly}/h, 월 $${cheapOD.monthly})로, 최고가 대비 <b>${gap}%</b> 저렴합니다.`);
}
if (cheapSpot && cheapOD) {
  const save = ((1 - cheapSpot.hourly / cheapOD.hourly) * 100).toFixed(0);
  insights.push(`스팟 최저가(<b>${esc(cheapSpot.provider)} ${esc(cheapSpot.instance)}</b>, $${cheapSpot.hourly}/h)는 온디맨드 최저가보다 약 <b>${save}%</b> 저렴합니다. 중단 허용 워크로드에 검토할 만합니다.`);
}
insights.push(changes.length ? `이번 주 요금 변동이 <b>${changes.length}건</b> 감지되었습니다.` : '이번 주 요금 변동은 없었습니다.');

// ---------- HTML ----------
const th = 'style="text-align:left;padding:6px 10px;border-bottom:2px solid #ddd;background:#f6f7f9;font-size:13px"';
const td = 'style="padding:6px 10px;border-bottom:1px solid #eee;font-size:13px"';
const table = (heads, rows) => `<table style="border-collapse:collapse;width:100%;margin:8px 0 20px">
<tr>${heads.map(h => `<th ${th}>${h}</th>`).join('')}</tr>
${rows.length ? rows.map(r => `<tr>${r.map(c => `<td ${td}>${c}</td>`).join('')}</tr>`).join('') : `<tr><td ${td} colspan="${heads.length}">데이터 없음</td></tr>`}
</table>`;
const period = `${startDate} ~ ${now.toFormat('yyyy-MM-dd')}`;

const html = `<div style="font-family:Apple SD Gothic Neo,Malgun Gothic,Arial,sans-serif;max-width:720px;color:#222">
<h2 style="margin:0 0 4px">멀티클라우드 주간 리포트</h2>
<div style="color:#666;font-size:13px;margin-bottom:16px">${period} · GCP / AWS / Azure · 자동 생성(n8n)</div>

<h3 style="margin:16px 0 6px">핵심 요약</h3>
<ul style="margin:0 0 16px;padding-left:20px;font-size:14px;line-height:1.7">${insights.map(s => `<li>${s}</li>`).join('')}</ul>

<h3 style="margin:16px 0 6px">1. 제공사별 장애 현황 (지난 7일)</h3>
${table(['제공사', '장애 건수', '누적 지속시간', '진행 중', '서울 관련'],
  byProv.map(b => [b.p, b.count, fmtMin(b.mins), b.ongoing, b.seoul]))}

<h3 style="margin:16px 0 6px">2. 지속시간 상위 장애</h3>
${table(['제공사', '서비스', '리전', '시작(KST)', '지속'],
  top.map(r => [esc(r.provider), esc(r.service), esc(String(r.regions).slice(0, 40)), kst(r.started_at), fmtMin(r.mins) + (r.ongoing ? ' (진행 중)' : '')]))}

<h3 style="margin:16px 0 6px">3. 서울 리전 VM 요금 비교 (4 vCPU / 16GB, ${esc(latestDate)} 기준)</h3>
${table(['과금', '제공사', '인스턴스', '시간당', '월 환산(730h)', ''],
  latest.map(r => [r.pricing, esc(r.provider), esc(r.instance), '$' + r.hourly, '$' + r.monthly, isTrue(r.cheapest) ? '✅ 최저가' : '']))}

<h3 style="margin:16px 0 6px">4. 이번 주 요금 변동</h3>
${table(['날짜', '제공사', '인스턴스', '과금', '이전 → 현재', '변동률'],
  changes.map(r => [esc(r.date), esc(r.provider), esc(r.instance), esc(r.pricing), `$${r.prev_hourly_usd} → $${r.hourly_usd}`, `${r.change_pct}%`]))}

<div style="color:#999;font-size:12px;margin-top:24px;line-height:1.6">
※ 장애 지속시간은 각 사 공개 상태 페이지에 게시된 시작~종료 시각 기준이며, 실제 서비스 영향 시간과 다를 수 있습니다.<br>
※ 요금은 각 사 공개 가격 API(Azure Retail Prices, GCP Cloud Billing Catalog)의 Linux 정가 기준이며 할인·약정은 반영하지 않았습니다.
</div></div>`;

const summary = `📊 주간 리포트 (${period})\n` +
  byProv.map(b => `${b.p}: 장애 ${b.count}건 / ${fmtMin(b.mins)}`).join('\n') +
  (cheapOD ? `\n💰 온디맨드 최저가: ${cheapOD.provider} ${cheapOD.instance} $${cheapOD.hourly}/h` : '') +
  `\n📧 상세 내용은 메일을 확인하세요.`;

return [{ json: { subject: `[주간] 멀티클라우드 장애·요금 리포트 (${period})`, html, summary } }];
